{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "Section 1 would add \"or public charter school\" to a provision in Section 49-3-103(d)(3) that begins \"Explain how an LEA.\"",
      "rationale": "Identifies the amendment target and the language extending the provision to public charter schools."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "Funding a student generates would go through the state department of education to the LEA where the student is a member, for as long as the student is a member. There are two exceptions. Funding generated under subdivision (c)(3) would stay with the department. The state share of funding that a charter school student generates would go straight to the charter school.",
      "rationale": "Covers the department's allocation role, membership-based duration, and both exceptions."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "Membership would start on the student's first day and end on the last day. A student who graduates early would count as a member until the expected graduation date for funding purposes.",
      "rationale": "States the membership period and the early-graduation funding exception."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "Section 3 would add \"or public charter school\" after \"LEA\" in Section 49-3-316(c).",
      "rationale": "Identifies the target subsection and conveys the extension of its LEA references to public charter schools."
    },
    {
      "proposition_id": "P5",
      "status": "partial",
      "summary_quote": "The commissioner of education, with the comptroller, would set up a standard financial accounting and reporting system for all charter schools. It would be designed to allow comparisons across years and agencies and to show the sources and uses of all funds.",
      "rationale": "Covers the responsible officials, system scope, and design objectives, but omits revision as necessary and the required forms or documentation."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "The commissioner would review charter school fiscal records to make sure spending is properly accounted for and safeguarded.",
      "rationale": "Conveys the mandatory review and its accounting and safeguarding purposes; the general reference to spending encompasses the listed expenditure categories."
    },
    {
      "proposition_id": "P7",
      "status": "full",
      "summary_quote": "The commissioner could also require charter schools that receive state education funding to follow one or more of the requirements that apply to LEAs in that section, as the commissioner considers appropriate.",
      "rationale": "Covers the commissioner's discretion, eligible charter schools, and application of LEA requirements from the identified section."
    },
    {
      "proposition_id": "P8",
      "status": "full",
      "summary_quote": "Section 4 would replace Section 49-13-112(a). A local board of education would have to give each charter school an amount equal to four items. The first is the local student-generated funds for its member students for the prior year.",
      "rationale": "Identifies the obligated board, recipient, local student-generated funding amount, and prior-year membership basis within the summary's TISA funding context."
    },
    {
      "proposition_id": "P9",
      "status": "partial",
      "summary_quote": "The second is the average per-pupil state and local funds above those the TISA requires.",
      "rationale": "Identifies above-TISA state and local funding, but omits that the district receives it in the current year and that allocation is for each prior-year charter member student."
    },
    {
      "proposition_id": "P10",
      "status": "partial",
      "summary_quote": "The third is the per-student state and local funds received for members beyond the prior year's membership.",
      "rationale": "Conveys funding for membership growth, but does not specify current-year charter membership or that the funds are received by the LEA."
    },
    {
      "proposition_id": "P11",
      "status": "full",
      "summary_quote": "The fourth is all appropriate federal allocations, including IDEA and ESEA funds.",
      "rationale": "Within the list of required local-board allocations, covers appropriate federal funding and both named programs."
    },
    {
      "proposition_id": "P12",
      "status": "full",
      "summary_quote": "The department of education would pay charter schools directly the state student-generated funds for the prior year.",
      "rationale": "Conveys direct departmental payment of the prior-year state student-generated amount; the surrounding discussion supplies the charter-member and TISA context."
    },
    {
      "proposition_id": "P13",
      "status": "partial",
      "summary_quote": "Federal funds the LEA receives would go to charter schools through joint agreements for shared services or through sub-grants for an equitable share, following department policies.",
      "rationale": "Covers both disbursement methods and departmental policies, but omits the limitation to LEA-authorized charter schools and the eligible-student basis for equitable shares."
    },
    {
      "proposition_id": "P14",
      "status": "partial",
      "summary_quote": "Each LEA would list in its budget the per-pupil local amount it will pass to charter schools, with its calculations.",
      "rationale": "Covers budget disclosure, but omits the upcoming-school-year timeframe and the requirement that actual allocations be based on those calculated amounts."
    },
    {
      "proposition_id": "P15",
      "status": "full",
      "summary_quote": "It would pay the local funds in at least nine equal installments, the same way state funds are paid.",
      "rationale": "In context, identifies the LEA's local-fund payments to charter schools and preserves the minimum installment count, equality, and distribution manner."
    },
    {
      "proposition_id": "P16",
      "status": "full",
      "summary_quote": "It would adjust payments at least in October, February, and June to reflect changes in revenue, membership, or services.",
      "rationale": "Covers the LEA's local-payment adjustments, all required months, and all adjustment grounds."
    },
    {
      "proposition_id": "P17",
      "status": "full",
      "summary_quote": "Charter schools must spend funds according to their budget, or as their governing body revises it, subject to state and federal law.",
      "rationale": "Conveys the budget-based spending requirement, governing-body revision authority, and state and federal legal constraints."
    },
    {
      "proposition_id": "P18",
      "status": "full",
      "summary_quote": "Sections 1 and 3 would take effect when the bill becomes law. Sections 2 and 4 would also take effect then for rulemaking. For all other purposes, they would take effect July 1, 2025.",
      "rationale": "Accurately states each section group's effective date and the rulemaking exception."
    }
  ]
}
